mapper.select:
SELECT id, number, status, user_id, address_book_id, order_time, checkout_time, pay_method, pay_status, amount, remark, phone, address, user_name, consignee, cancel_reason, rejection_reason, cancel_time, estimated_delivery_time, delivery_status, delivery_time, pack_amount, tableware_number, tableware_status FROM orders WHERE user_id = #{userID}
AND status = #{status}
ORDER BY order_time DESC
LIMIT #{page}, #{pageSize}

select count(id)
from orders
where user_id = #{userID}

    and status = #{orderHistoryDTO.status}

select * from orders


        and number like concat('%',#{number},'%')


        and phone like concat('%',#{phone},'%')


        and user_id = #{userId}


        and status = #{status}


        and order_time >= #{beginTime}


        and order_time <= #{endTime}


order by order_time desc

select sum(amount) from orders


        and order_time > #{begin}


        and order_time < #{end}


        and status = #{status}

select count(id) from user


        and create_time > #{begin}


        and create_time < #{end}

select count(id) from orders


        and order_time > #{begin}


        and order_time < #{end}


        and status = #{status}

select od.name, sum(od.number) number
from order_detail od,
orders o
where od.order_id = o.id
and o.status = 5

    and o.order_time > #{begin}


    and o.order_time < #{end}

group by od.name
order by number desc
limit 0, 10;
